unitsize(2cm);

pair A, B, O, P, C, D;

A = .4;
B = 1.2;
O = 0;
P = 0 + 1*dir(90);
C = (3/2, 5/3);
D = (-1/2, 5/3);

draw((-0.5,0)--(2,0));
draw((0,-1)--(0,1));
draw(C--D);
draw(O--C,dashed);
draw(O--D,dashed);
draw(P--A--B--cycle);

label("$A$", A, S);
label("$B$", B, S);
label("$E$", O, S);
label("$P$", P, N);
label("$C$", C, N);
label("$D$", D, N);
[/asy]

